{
  "name": "gap_pairs_topk_001",
  "intuition": "Create pairwise preferences only when one candidate’s objective is better by at least a threshold, then keep the strongest (largest margin) pairs up to a global budget to avoid quadratic blowup.",
  "implementation_hint": {
    "expects": [
      "objective",
      "log_prob"
    ],
    "returns": "PrefBatch",
    "mode": "pairwise"
  },
  "code": "def generated_builder(feature_cache, extra):
    objective = feature_cache['objective']
    # Lower objective is better.
    gap_thr = extra.get('gap_threshold', 0.0)
    max_pairs = extra.get('max_pairs', 256)

    # Avoid relying on float()/int() builtins; coerce gently via arithmetic.
    try:
        gap_thr = gap_thr * 1.0
    except Exception:
        gap_thr = 0.0
    try:
        max_pairs = max_pairs + 0
    except Exception:
        max_pairs = 256

    diff = objective[:, :, None] - objective[:, None, :]
    cand = diff < (-gap_thr)
    b_idx, w_idx, l_idx = cand.nonzero(as_tuple=True)

    # Ensure int64 1D indices.
    b_idx = b_idx.to(dtype=objective.new_empty((0,), dtype=objective.dtype).long().dtype)
    w_idx = w_idx.to(dtype=b_idx.dtype)
    l_idx = l_idx.to(dtype=b_idx.dtype)

    if b_idx.numel() == 0:
        empty = b_idx
        return PrefBatch(
            mode='pairwise',
            pair_idx=(empty, empty, empty),
            weight=None,
            meta={'builder': 'gap_pairs_topk', 'gap_threshold': gap_thr, 'max_pairs': max_pairs}
        )

    margin = (-diff[b_idx, w_idx, l_idx])

    if max_pairs > 0 and b_idx.numel() > max_pairs:
        _, topk = margin.topk(max_pairs, largest=True)
        b_idx = b_idx[topk]
        w_idx = w_idx[topk]
        l_idx = l_idx[topk]

    return PrefBatch(
        mode='pairwise',
        pair_idx=(b_idx, w_idx, l_idx),
        weight=None,
        meta={'builder': 'gap_pairs_topk', 'gap_threshold': gap_thr, 'max_pairs': max_pairs}
    )"
}

{
  "name": "gap_pairs_topk_002",
  "intuition": "Build pairwise preferences only for clearly better candidates: for each batch item, create (winner, loser) when the winner’s objective is lower by at least `gap_threshold`, and keep only the globally largest objective gaps up to `max_pairs` to control pair explosion.",
  "implementation_hint": {
    "expects": [
      "objective",
      "log_prob"
    ],
    "returns": "PrefBatch",
    "mode": "pairwise"
  },
  "code": "def generated_builder(feature_cache, extra):
    objective = feature_cache['objective']
    # Lower objective is better.
    gap_thr = extra.get('gap_threshold', 0.0)
    max_pairs = extra.get('max_pairs', 256)

    # Coerce types without using banned builtins like float()/int().
    try:
        gap_thr = gap_thr * 1.0
    except Exception:
        gap_thr = 0.0
    try:
        max_pairs = max_pairs + 0
    except Exception:
        max_pairs = 256

    B, N = objective.shape[0], objective.shape[1]

    # diff[b, i, j] = obj_i - obj_j; i beats j when diff < -gap_thr.
    diff = objective[:, :, None] - objective[:, None, :]
    cand = diff < (-gap_thr)

    # Exclude self-pairs explicitly.
    eye = torch.eye(N, dtype=torch.bool, device=objective.device).unsqueeze(0)
    cand = cand & (~eye)

    b_idx, w_idx, l_idx = cand.nonzero(as_tuple=True)

    if b_idx.numel() == 0:
        empty = b_idx
        return PrefBatch(
            mode='pairwise',
            pair_idx=(empty, empty, empty),
            weight=None,
            meta={'builder': 'gap_pairs_topk', 'gap_threshold': gap_thr, 'max_pairs': max_pairs}
        )

    # Positive margin: how much better winner is than loser.
    margin = (-diff[b_idx, w_idx, l_idx])

    # Select strongest margins up to global budget.
    if (max_pairs > 0) and (b_idx.numel() > max_pairs):
        _, topk = margin.topk(max_pairs, largest=True)
        b_idx = b_idx[topk]
        w_idx = w_idx[topk]
        l_idx = l_idx[topk]

    # Optionally provide non-negative weights equal to margin.
    weight = margin
    if (max_pairs > 0) and (weight.numel() > max_pairs):
        weight = weight[topk]

    return PrefBatch(
        mode='pairwise',
        pair_idx=(b_idx, w_idx, l_idx),
        weight=weight,
        meta={'builder': 'gap_pairs_topk', 'gap_threshold': gap_thr, 'max_pairs': max_pairs}
    )"
}

{
  "name": "builder_all_pairs_gap_weight_001",
  "intuition": "Keep all objective-consistent pairs but weight them by objective gap (with a configurable floor) so clearer wins contribute more signal while near-ties still contribute minimally, improving robustness to noisy objectives.",
  "implementation_hint": {
    "expects": [
      "objective",
      "log_prob"
    ],
    "returns": "PrefBatch",
    "mode": "pairwise"
  },
  "code": "def generated_builder(feature_cache, extra):
    objective = feature_cache['objective']
    # All objective-consistent pairs (lower is better): winner has lower objective.
    mask = objective[:, :, None] < objective[:, None, :]
    b_idx, winner_idx, loser_idx = mask.nonzero(as_tuple=True)

    # Nonnegative weight based on objective gap; configurable floor to avoid zeroing near-ties.
    gap_floor = 0.0
    if extra is not None and 'gap_floor' in extra and extra['gap_floor'] is not None:
        gap_floor = float(extra['gap_floor'])
        if gap_floor < 0.0:
            gap_floor = 0.0

    gaps = objective[b_idx, loser_idx] - objective[b_idx, winner_idx]
    weight = gaps
    if gap_floor > 0.0:
        weight = weight + gap_floor

    return PrefBatch(mode='pairwise', pair_idx=(b_idx, winner_idx, loser_idx), weight=weight, meta={'builder': 'all_pairs_gap_weight', 'gap_floor': gap_floor})
"
}

{
  "name": "builder_all_pairs_gap_threshold_001",
  "intuition": "Filter out near-tie objective comparisons (configurable gap_threshold) so pairwise labels focus on clearer wins/losses, reducing noisy gradients while keeping full coverage when threshold is 0.",
  "implementation_hint": {
    "expects": [
      "objective",
      "log_prob"
    ],
    "returns": "PrefBatch",
    "mode": "pairwise"
  },
  "code": "def generated_builder(feature_cache, extra):\n    objective = feature_cache['objective']\n    # Keep only pairs with a clear gap to reduce label noise from near-ties.\n    gap_threshold = extra.get('gap_threshold', 0.0)\n    obj_w = objective[:, :, None]\n    obj_l = objective[:, None, :]\n    mask = (obj_w + gap_threshold) < obj_l\n    b_idx, winner_idx, loser_idx = mask.nonzero(as_tuple=True)\n    return PrefBatch(mode='pairwise', pair_idx=(b_idx, winner_idx, loser_idx), weight=None, meta={'builder': 'all_pairs_gap_threshold', 'gap_threshold': gap_threshold})\n"
}

{
  "name": "anchor_topk_tensor_k",
  "intuition": "For each instance, choose the lowest-objective candidate as a consistent anchor (winner) and pair it against the k highest-objective candidates (losers), yielding stable, high-signal preferences while avoiding self-pairs and using a deterministic all-pairs fallback when ties eliminate all pairs.",
  "implementation_hint": {
    "expects": [
      "objective",
      "log_prob"
    ],
    "returns": "PrefBatch",
    "mode": "pairwise"
  },
  "code": "def generated_builder(feature_cache, extra):
    objective = feature_cache['objective']  # [B, N], lower is better
    B, N = objective.shape

    # Determine k without using int() (may be removed). Accept python numbers or 0-d tensors.
    k_val = extra.get('k', 2)
    if k_val is None:
        k = 2
    else:
        if hasattr(k_val, 'numel') and callable(getattr(k_val, 'numel', None)):
            if k_val.numel() == 1:
                k = k_val.to(device='cpu').item()
            else:
                k = 2
        else:
            k = k_val

    # Coerce to a safe small positive python integer via arithmetic/clamping.
    try:
        k = k + 0
    except Exception:
        k = 2
    if k < 1:
        k = 1
    if N <= 1:
        k = 1
    else:
        if k > (N - 1):
            k = N - 1

    best_idx = objective.argmin(dim=1)  # [B]
    worst_k_idx = objective.topk(k, dim=1, largest=True, sorted=False).indices  # [B, k]

    best_rep = best_idx[:, None].expand(B, k)
    valid = worst_k_idx.ne(best_rep)

    b_grid = torch.arange(B, device=objective.device, dtype=torch.int64)[:, None].expand(B, k)
    b_idx = b_grid[valid].to(dtype=torch.int64).reshape(-1)
    winner_idx = best_rep[valid].to(dtype=torch.int64).reshape(-1)
    loser_idx = worst_k_idx[valid].to(dtype=torch.int64).reshape(-1)

    # Fallback: if ties/self-filtering eliminate all pairs, use strict all-pairs by objective.
    if b_idx.numel() == 0:
        mask = objective[:, :, None] < objective[:, None, :]
        b_idx, winner_idx, loser_idx = mask.nonzero(as_tuple=True)
        b_idx = b_idx.to(dtype=torch.int64).reshape(-1)
        winner_idx = winner_idx.to(dtype=torch.int64).reshape(-1)
        loser_idx = loser_idx.to(dtype=torch.int64).reshape(-1)

    # Ensure at least one pair even under total ties (gate requires min_pairs>=1).
    if b_idx.numel() == 0:
        if N >= 2:
            b_idx = torch.arange(B, device=objective.device, dtype=torch.int64)
            winner_idx = torch.zeros(B, device=objective.device, dtype=torch.int64)
            loser_idx = torch.ones(B, device=objective.device, dtype=torch.int64)
        else:
            b_idx = torch.zeros(1, device=objective.device, dtype=torch.int64)
            winner_idx = torch.zeros(1, device=objective.device, dtype=torch.int64)
            loser_idx = torch.zeros(1, device=objective.device, dtype=torch.int64)

    return PrefBatch(mode='pairwise', pair_idx=(b_idx, winner_idx, loser_idx), weight=None, meta={'builder': 'anchor_topk_tensor_k', 'k': k})
"
}

{
  "name": "loss_logsigmoid_003_cost_margin",
  "intuition": "Incorporate a cost-dependent margin into the pairwise logsigmoid argument: when the (detached) cost gap indicates the winner is much better, require a larger log-prob gap to achieve low loss; when the gap is small, keep the task easier. This stabilizes training by keeping the core pairwise objective while using a bounded, smooth margin term instead of a raw linear cost penalty that can shift the logit too aggressively.",
  "pseudocode": "gap = detach(cost_b - cost_a); margin = beta * tanh(gap / tau); loss = -logsigmoid(clamp(alpha*scale*(lpw-lpl) - margin, -20, 20))",
