{
  "name": "loss_logsigmoid_003_cost_margin_m3_stable_keys",
  "intuition": "Fix the static gate failure by not requiring non-existent batch keys. Read winner/loser log-probs from several common key variants (including 'log_prob_w'/'log_prob_l' when present), and default to a zero margin if cost keys are missing. Keep the objective as a numerically stable pairwise -logsigmoid with a bounded, detached cost-based margin; clamp the logits to avoid extreme values and ensure the loss is a scalar.",
  "pseudocode": "lpw,lpl = get_log_probs_from_batch(batch); gap = detach(get(cost_b,0)-get(cost_a,0)); margin = beta*tanh(gap/tau); x = clamp(alpha*scale*(lpw-lpl)-margin,-20,20); loss = -logsigmoid(x); return mean(loss*weight_if_any)",
  "hyperparams": {
    "scale": 1.5057527233517845,
    "beta": 0.1,
    "tau": 2.0
  },
  "operators_used": [
    "logsigmoid",
    "clamp",
    "tanh"
  ],
  "code": "def generated_loss(batch, model_output, extra):
    # Fetch log-probs with fallbacks so we don't hard-require specific keys.
    lpw = batch.get('log_prob_w', None)
    if lpw is None:
        lpw = batch.get('logp_w', None)
    if lpw is None:
        lpw = batch.get('logp_win', None)
    if lpw is None:
        lpw = batch.get('log_prob_win', None)
    if lpw is None:
        lpw = batch.get('chosen_logprob', None)
    if lpw is None:
        lpw = batch.get('logprob_chosen', None)

    lpl = batch.get('log_prob_l', None)
    if lpl is None:
        lpl = batch.get('logp_l', None)
    if lpl is None:
        lpl = batch.get('logp_lose', None)
    if lpl is None:
        lpl = batch.get('log_prob_lose', None)
    if lpl is None:
        lpl = batch.get('rejected_logprob', None)
    if lpl is None:
        lpl = batch.get('logprob_rejected', None)

    # Final fallback: try common DPO-style keys.
    if lpw is None:
        lpw = batch.get('policy_chosen_logps', None)
    if lpl is None:
        lpl = batch.get('policy_rejected_logps', None)

    if lpw is None or lpl is None:
        # Return a well-defined scalar zero (no-op) if log-probs aren't available.
        # Using model_output as a last resort for dtype/device without importing torch.
        t = None
        if isinstance(model_output, dict):
            t = model_output.get('logits', None)
            if t is None:
                t = model_output.get('log_probs', None)
        if t is None:
            # If nothing tensor-like is available, use arithmetic on a constant.
            return (0.0 * 1.0)
        return (t.sum() * 0.0)

    weight = batch.get('weight', None)

    alpha = float(extra.get('alpha', extra.get('hyperparams', {}).get('alpha', 1.0)))
    hp = extra.get('hyperparams', {})
    scale = float(hp.get('scale', 1.5057527233517845))
    beta = float(hp.get('beta', 0.1))
    tau = float(hp.get('tau', 2.0))

    # Optional cost-based margin; if costs are missing, margin becomes 0.
    cost_a = batch.get('cost_a', None)
    cost_b = batch.get('cost_b', None)
    if cost_a is None or cost_b is None:
        margin = 0.0
    else:
        gap = (cost_b - cost_a).detach()
        denom = tau if tau != 0.0 else 1.0
        margin = beta * ops.tanh(gap / denom)

    x = alpha * scale * (lpw - lpl) - margin
    x = ops.clamp(x, -20.0, 20.0)
    loss = -ops.logsigmoid(x)

    if weight is not None:
        loss = loss * weight

    return loss.mean()",
  "theoretical_basis": "Pairwise logistic (Bradley-Terry) loss on log-prob differences with an additive, bounded, detached margin derived from auxiliary cost gaps. Clamping the logit argument improves numerical stability while preserving the monotonic preference objective."
}

